        task = Task(id=1, title="t", due_at=now - timedelta(hours=1), created_at=now)
        assert task.is_overdue(now) is True

    def test_not_overdue_when_due_in_future(self, now):
        task = Task(id=1, title="t", due_at=now + timedelta(hours=1), created_at=now)
        assert task.is_overdue(now) is False

    def test_not_overdue_when_done(self, now):
        task = Task(
            id=1, title="t",
            due_at=now - timedelta(hours=1),
            status=TaskStatus.DONE,
            created_at=now,
        )
        assert task.is_overdue(now) is False

    def test_not_overdue_when_no_due_date(self, now):
        task = Task(id=1, title="t", created_at=now)
        assert task.is_overdue(now) is False

