"""Tests for tasks_api.queries — TaskQuery, TaskPage, apply_query."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, created_at=None, tags=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


# ── TaskQuery validation ────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101])
    def test_invalid_limit(self, limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=limit)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  ShOp  ")
        assert q.tag == "shop"

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


# ── TaskPage.has_more ────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_task(1)], total=1, limit=10, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact_fit(self):
        page = TaskPage(items=[_task(1), _task(2)], total=2, limit=2, offset=0)
        assert page.has_more is False


# ── apply_query filtering ────────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Alpha", status=TaskStatus.PENDING, priority=TaskPriority.HIGH,
                  tags=[Tag("work")]),
            _task(2, "Beta", status=TaskStatus.DONE, priority=TaskPriority.LOW,
                  tags=[Tag("home")]),
            _task(3, "Gamma search", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
                  due_at=NOW - timedelta(hours=1), tags=[Tag("work"), Tag("urgent")]),
        ]

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="work"), NOW)
        assert {t.id for t in page.items} == {1, 3}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="search"), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 3

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="ALPHA"), NOW)
        assert len(page.items) == 1

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        ids = {t.id for t in page.items}
        assert 3 not in ids
        assert 1 in ids

    def test_combined_filters(self, tasks):
        page = apply_query(
            tasks, TaskQuery(status=TaskStatus.PENDING, tag="work"), NOW
        )
        assert {t.id for t in page.items} == {1, 3}

    def test_no_match(self, tasks):
        page = apply_query(tasks, TaskQuery(search="nonexistent"), NOW)
        assert len(page.items) == 0
        assert page.total == 0


# ── apply_query sorting ──────────────────────────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Banana", priority=TaskPriority.LOW,
                  created_at=NOW - timedelta(hours=2)),
            _task(2, "Apple", priority=TaskPriority.HIGH,
                  created_at=NOW - timedelta(hours=1),
                  due_at=NOW + timedelta(days=1)),
            _task(3, "Cherry", priority=TaskPriority.MEDIUM,
                  created_at=NOW),
        ]

    def test_sort_by_title_ascending(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_descending(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.title for t in page.items] == ["Cherry", "Banana", "Apple"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        assert priorities == [TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW]

    def test_sort_by_created_at(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Task 2 has a due_at, tasks 1 & 3 have None (sort last)
        assert page.items[0].id == 2


# ── apply_query pagination ───────────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_task(i, f"Task {i}") for i in range(1, 6)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=3), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_end(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=10, offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 5

    def test_full_page(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=100), NOW)
        assert len(page.items) == 5
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, id=1, title="Test"):
        return Task(id=id, title=title)

    def test_add_and_get(self, repo):
        task = self._make_task()
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task(1))

    def test_list_returns_snapshot(self, repo):
        repo.add(self._make_task(1, "A"))
        repo.add(self._make_task(2, "B"))
        items = list(repo.list())
        assert len(items) == 2

    def test_update_existing(self, repo):
        task = self._make_task()
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(999))

    def test_delete_existing(self, repo):
        repo.add(self._make_task())
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates_by_name(self):
        result = normalize_tags([Tag("hello"), Tag("HELLO")])
        assert len(result) == 1
        assert result[0].name == "hello"

    def test_accepts_strings(self):
        result = normalize_tags(["foo", "bar"])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_mixed_tags_and_strings(self):
        result = normalize_tags([Tag("alpha"), "ALPHA", "beta"])
        assert len(result) == 2

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["c", "a", "b", "A"])
        assert [t.name for t in result] == ["c", "a", "b"]
